@layer hj.components {
  /*
   * Customise: --hj-tabs-gap · --hj-tabs-height · --hj-tabs-indicator (colour) · --hj-tabs-radius (pill)
   * The indicator spans the whole list and is clipped to the active tab with Base UI's
   * --active-tab-* offsets — it moves without animating width or left.
   */
  .hj-tabs-root {
    display: flex;
    flex-direction: column;
    gap: var(--hj-space-4);
    min-width: 0;
    font-family: var(--hj-font-sans);
  }
  .hj-tabs-root[data-orientation='vertical'] {
    flex-direction: row;
  }

  .hj-tabs-list {
    --_h: var(--hj-tabs-height, 44px);
    position: relative;
    z-index: 0;
    display: flex;
    align-items: stretch;
    gap: var(--hj-tabs-gap, var(--hj-space-6));
    min-width: 0;
    overflow-x: auto;
    scrollbar-width: none;
    box-shadow: inset 0 -1px 0 var(--hj-line);
  }
  .hj-tabs-list::-webkit-scrollbar {
    display: none;
  }
  .hj-tabs-list[data-size='sm'] {
    --_h: var(--hj-tabs-height, 36px);
    gap: var(--hj-tabs-gap, var(--hj-space-5));
  }
  .hj-tabs-list[data-orientation='vertical'] {
    flex-direction: column;
    gap: 2px;
    box-shadow: inset -1px 0 0 var(--hj-line);
  }

  .hj-tabs-tab {
    position: relative;
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: var(--_h);
    padding: 0 2px;
    border: 0;
    background: none;
    color: var(--hj-fg-dim);
    font: 600 14.5px / 1 var(--hj-font-sans);
    letter-spacing: -0.005em;
    white-space: nowrap;
    cursor: pointer;
    user-select: none;
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-tabs-list[data-size='sm'] .hj-tabs-tab {
    font-size: 13.5px;
  }
  .hj-tabs-list[data-fill] .hj-tabs-tab {
    flex: 1 1 0;
  }
  .hj-tabs-list[data-orientation='vertical'] .hj-tabs-tab {
    justify-content: flex-start;
    padding: 0 16px 0 2px;
  }
  .hj-tabs-tab:hover:not([data-disabled]) {
    color: var(--hj-fg);
  }
  .hj-tabs-tab[data-active] {
    color: var(--hj-fg);
  }
  .hj-tabs-tab:active:not([data-disabled]) {
    transform: scale(var(--hj-press));
    transition-duration: var(--hj-dur-fast), 70ms;
  }
  .hj-tabs-tab[data-disabled] {
    opacity: 0.4;
    cursor: not-allowed;
  }
  .hj-tabs-tab:focus-visible {
    outline-offset: -2px;
    border-radius: var(--hj-radius-xs);
  }
  .hj-tabs-tab .hj-icon {
    font-size: 18px;
  }

  /* Underline: a 2px accent rule, clipped to the active tab. */
  .hj-tabs-indicator {
    position: absolute;
    z-index: -1;
    inset: auto 0 0 0;
    height: 2px;
    border-radius: 2px;
    background: var(--hj-tabs-indicator, var(--hj-accent));
    pointer-events: none;
    clip-path: inset(0 var(--active-tab-right, 50%) 0 var(--active-tab-left, 50%) round 2px);
  }
  .hj-tabs-list[data-orientation='vertical'] .hj-tabs-indicator {
    inset: 0 0 0 auto;
    width: 2px;
    height: auto;
    clip-path: inset(var(--active-tab-top, 50%) 0 var(--active-tab-bottom, 50%) 0 round 2px);
  }
  /* Animate only after the first measured frame: the first position is assigned, not swept. */
  .hj-tabs-list[data-ready] .hj-tabs-indicator {
    transition: clip-path var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }

  /* Pill: a track with an accent-soft pill under the active tab. */
  .hj-tabs-list[data-variant='pill'] {
    --_h: var(--hj-tabs-height, 32px);
    align-self: flex-start;
    gap: 0;
    padding: 4px;
    border-radius: var(--hj-tabs-radius, var(--hj-radius-pill));
    background: var(--hj-surface);
    box-shadow: inset 0 0 0 1px var(--hj-line);
  }
  .hj-tabs-list[data-variant='pill'][data-size='sm'] {
    --_h: var(--hj-tabs-height, 26px);
    padding: 3px;
  }
  .hj-tabs-list[data-variant='pill'][data-fill] {
    align-self: stretch;
  }
  .hj-tabs-list[data-variant='pill'] .hj-tabs-tab {
    padding: 0 14px;
    border-radius: var(--hj-tabs-radius, var(--hj-radius-pill));
    font-size: 13.5px;
  }
  .hj-tabs-list[data-variant='pill'][data-size='sm'] .hj-tabs-tab {
    padding: 0 11px;
    font-size: 12.5px;
  }
  /* 44px hit area around a 32px pill */
  .hj-tabs-list[data-variant='pill'] .hj-tabs-tab::before {
    content: '';
    position: absolute;
    inset: -6px 0;
  }
  .hj-tabs-list[data-variant='pill'] .hj-tabs-tab[data-active] {
    color: var(--hj-accent);
  }
  .hj-tabs-list[data-variant='pill'] .hj-tabs-indicator {
    inset: 0;
    height: auto;
    border-radius: 0;
    background: var(--hj-tabs-indicator, var(--hj-accent-soft));
    clip-path: inset(
      var(--active-tab-top, 50%) var(--active-tab-right, 50%) var(--active-tab-bottom, 50%)
        var(--active-tab-left, 50%) round var(--hj-tabs-radius, var(--hj-radius-pill))
    );
  }

  /* Panels arrive from the side the user moved toward — a short, faded step. */
  .hj-tabs-panel {
    min-width: 0;
    outline: none;
    animation: hj-tabs-panel-in var(--hj-dur-gentle-settle) var(--hj-ease-gentle-settle);
  }
  .hj-tabs-panel[data-activation-direction='left'] {
    --_dx: -1;
  }
  .hj-tabs-panel[data-activation-direction='right'] {
    --_dx: 1;
  }
  .hj-tabs-panel:focus-visible {
    outline: 2px solid var(--hj-focus);
    outline-offset: 4px;
    border-radius: var(--hj-radius-xs);
  }
  @keyframes hj-tabs-panel-in {
    from {
      opacity: 0;
      transform: translateX(calc(8px * var(--_dx, 0) * var(--hj-travel)));
    }
  }
}

'use client';
import { Tabs as Base } from '@base-ui/react/tabs';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { part } from '../../system/part.tsx';
import type { HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

export const Root: HanjiPart<typeof Base.Root> = part(Base.Root, 'Tabs.Root', 'hj-tabs-root');
export const Tab: HanjiPart<typeof Base.Tab> = part(Base.Tab, 'Tabs.Tab', 'hj-tabs-tab');
export const Indicator: HanjiPart<typeof Base.Indicator> = part(
  Base.Indicator,
  'Tabs.Indicator',
  'hj-tabs-indicator',
);
export const Panel: HanjiPart<typeof Base.Panel> = part(Base.Panel, 'Tabs.Panel', 'hj-tabs-panel');

export interface ListOwnProps {
  /** underline = a 2px accent rule under the active tab · pill = an accent-soft pill in a track. */
  variant?: 'underline' | 'pill';
  /** Tab height: sm 36 · md 44 (underline) / 40 track (pill). */
  size?: 'sm' | 'md';
  /** Render the moving indicator after the tabs. Turn off to place your own `Tabs.Indicator`. */
  indicator?: boolean;
  /** Stretch tabs to share the list's width equally. */
  fill?: boolean;
}
export interface ListProps extends ListOwnProps, Base.List.Props {}

/**
 * The row of tabs. Draws the indicator, which follows the active tab by clipping (never by
 * animating width or left), and starts moving only after the first measured frame so it
 * doesn't sweep in on page load.
 */
export function List(props: ListProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    variant = 'underline',
    size = 'md',
    indicator = true,
    fill = false,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Tabs.List', props);
  const [ready, setReady] = React.useState(false);
  React.useEffect(() => {
    // The first measured position is assigned, not animated (hanji segmented-track rule).
    const id = requestAnimationFrame(() => requestAnimationFrame(() => setReady(true)));
    return () => cancelAnimationFrame(id);
  }, []);
  return (
    <Base.List
      {...rest}
      data-variant={variant}
      data-size={size}
      data-fill={flag(fill)}
      data-ready={flag(ready)}
      className={cls(config, 'Tabs.List', 'hj-tabs-list', className)}
    >
      {children}
      {indicator ? <Indicator /> : null}
    </Base.List>
  );
}
